const MSG_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function fmtRp(n) {
  const v = Math.round(Number(n) || 0);
  return (v < 0 ? '-' : '') + 'Rp' + String(Math.abs(v)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function fmtDate(d) {
  const [y, m, day] = String(d).slice(0, 10).split('-').map(Number);
  return MSG_MONTHS[m - 1] ? `${day} ${MSG_MONTHS[m - 1]} ${y}` : String(d);
}

// '2026-11' -> 'Nov 2026'
function msgMonth(ym) {
  const [y, m] = String(ym).split('-').map(Number);
  return `${MSG_MONTHS[m - 1]} ${y}`;
}

function msgPlural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

function msgLine(r, names) {
  const review = r.status === 'needs_review';
  const parts = [fmtRp(r.amount)];
  if (r.type === 'transfer') parts.push(`${r.account} → ${r.to_account}`);
  else parts.push(names[r.category_id] || r.category_id, r.account);
  const label = r.note || r.merchant;
  if (label) parts.push(`"${label}"`);
  if (r.nature) parts.push(r.nature);
  return `${review ? '⚠️' : '✅'} ${parts.join(' · ')}  (#${r.id})${review ? ' · needs review' : ''}`;
}

// One entry on one line for /review and /last: mark, id, date, amount, where, label
function msgBrief(r) {
  const mark = r.status === 'needs_review' ? '⚠️' : '✅';
  const where = r.type === 'transfer' ? `${r.account} → ${r.to_account}` : `${r.category_id} · ${r.account}`;
  const label = r.merchant || r.note;
  return `${mark} #${r.id} · ${fmtDate(r.txn_date)} · ${fmtRp(r.amount)} · ${where}${label ? ` · "${label}"` : ''}`;
}

const MSG_LIST_MAX = 30;

function msgList(rows) {
  const lines = rows.slice(0, MSG_LIST_MAX).map(msgBrief);
  if (rows.length > MSG_LIST_MAX) lines.push(`… and ${rows.length - MSG_LIST_MAX} more`);
  return lines;
}

const MSG = {
  // rows: Transactions row objects of one batch; categories: Categories rows (for names)
  saved(rows, categories) {
    const names = {};
    for (const c of categories || []) names[c.id] = c.name;
    return rows.map((r, i) => msgLine(r, names) + (i === rows.length - 1 ? ' · /undo' : '')).join('\n');
  },
  askAmount(text) {
    const eg = text ? `${text} 18rb` : '18rb';
    return `❓ How much was it? Reply with the amount, e.g. "${eg}".`;
  },
  askMissing(missing, hint) {
    const what = (missing || []).join(', ');
    return `❓ I need a bit more info${what ? `: ${what}` : ''}.${hint ? ` ${hint}` : ''} Please send it again with the details.`;
  },
  reviewOldDate(date) {
    return `Check the date: ${fmtDate(date)} is more than two months back.`;
  },
  reviewOpening(account, openingDate) {
    return `Check: dated on or before the ${account} opening balance (${fmtDate(openingDate)}), so it may be counted twice. /undo if so.`;
  },
  reviewTransfer(account) {
    return `Check: saved as a transfer to your own ${account}. If you paid someone else, /undo and send it again with a caption, e.g. "bayar utang 100rb".`;
  },
  photoTooLong() {
    return '❓ This screenshot is too long to read: Telegram shrinks it and the text gets too small. Nothing was saved. Send shorter screenshots instead, about two screens each.';
  },
  futureDate() {
    return '❓ That date is in the future. For upcoming payments, add a rule in the Recurring tab.';
  },
  badAccount(name, accounts) {
    const list = (accounts || []).map((a) => a.account).join(', ');
    return `❓ I don't know the account "${name}". Accounts: ${list}.`;
  },
  badCategory(id) {
    return `❓ The category "${id}" is missing or inactive. Check the Categories tab, then send it again.`;
  },
  needToAccount() {
    return '❓ Which account did the money go to? Send it again with the destination account.';
  },
  sameAccount() {
    return '❓ A transfer needs two different accounts. Send it again with the right ones.';
  },
  error(text, reason) {
    const what = text ? `"${text}"` : 'your message';
    return `🔴 Couldn't process ${what} (${reason || 'the AI service did not respond'}). Please send it again.`;
  },
  pending(n) {
    return `📥 Processing ${msgPlural(n, 'pending message', 'pending messages')}`;
  },
  reviewHint() {
    return 'All correct? Send /ok. Otherwise /review shows how to fix them.';
  },
  reviewList(rows) {
    return [
      `⚠️ ${msgPlural(rows.length, 'entry needs', 'entries need')} review`,
      ...msgList(rows),
      'All correct: /ok · some correct: /ok 16 25 · wrong: /undo 25, then send that one again as text.',
    ].join('\n');
  },
  reviewNone() {
    return 'Nothing needs review.';
  },
  confirmed(ids) {
    return `✅ Confirmed ${msgPlural(ids.length, 'entry', 'entries')} (${ids.map((i) => '#' + i).join(', ')}).`;
  },
  // what: 'void' for /undo, 'confirm' for /ok
  badIds(tokens, what) {
    const why = what === 'confirm' ? 'not found or not waiting for review' : 'not found or already void';
    return `❓ Nothing changed: ${tokens.join(', ')} ${why}. Send /${what === 'confirm' ? 'review' : 'last'} to see the ids.`;
  },
  last(rows) {
    return rows.length ? ['Latest entries', ...msgList(rows)].join('\n') : 'No entries yet.';
  },
  voided(ids) {
    return `↩️ Voided ${msgPlural(ids.length, 'entry', 'entries')} (${ids.map((i) => '#' + i).join(', ')}).`;
  },
  nothingToVoid() {
    return 'Nothing to void.';
  },
  // accounts: [{account, balance}], liquidTotal: number
  balance(accounts, liquidTotal) {
    const lines = accounts.map((a) => `${a.account} · ${fmtRp(a.balance)}`);
    return ['Balance', ...lines, `Liquid total · ${fmtRp(liquidTotal)}`].join('\n');
  },
  summaryUsage() {
    return '❓ Which month? Send "/summary" for this month or e.g. "/summary 2026-10".';
  },
  summaryEmpty(month) {
    return `No entries in ${msgMonth(month)}.`;
  },
  // d: the totals built by cSummary (commands.js)
  summary(d) {
    const pct = (n) => `${d.expense ? Math.round((n / d.expense) * 100) : 0}%`;
    const pairs = (list) => list.map((x) => `${x.name} ${fmtRp(x.amount)}`).join(' · ');
    const out = [
      `Summary · ${msgMonth(d.month)}${d.to ? ` (to ${fmtDate(d.to)})` : ''}`,
      `Income · ${fmtRp(d.income)}`,
      `Expense · ${fmtRp(d.expense)}`,
      `Net · ${fmtRp(d.income - d.expense)}`,
    ];
    if (d.expense) {
      out.push('', 'Expense by group');
      for (const g of d.groups) {
        out.push(`${g.name} · ${fmtRp(g.amount)} · ${pct(g.amount)}`);
        for (const s of g.subs) out.push(`   ${s.name} · ${fmtRp(s.amount)}`);
      }
      const unset = d.expense - d.need - d.want;
      out.push('', 'Need vs want', `Need · ${fmtRp(d.need)} · ${pct(d.need)}`, `Want · ${fmtRp(d.want)} · ${pct(d.want)}`);
      if (unset) out.push(`Not set · ${fmtRp(unset)} · ${pct(unset)}`);
      if (d.want) {
        out.push(`Top want · ${pairs(d.topWant)}`);
        out.push(`Want by day · weekday ${fmtRp(d.wantWeekday)} · weekend ${fmtRp(d.wantWeekend)}`);
        if (d.wantTimes.length) out.push(`Want by time · ${pairs(d.wantTimes)}`);
      }
    }
    if (d.irregular.length || d.irregularAvg) {
      out.push('', 'Irregular');
      for (const r of d.irregular) out.push(`${fmtDate(r.txn_date)} · ${fmtRp(r.amount)} · ${r.name}${r.label ? ` · "${r.label}"` : ''}`);
      out.push(`12-month average · ${fmtRp(d.irregularAvg)} a month`);
    }
    out.push('', `Freelance income · ${fmtRp(d.freelance)}`);
    if (d.review) out.push(`⚠️ ${msgPlural(d.review, 'entry needs', 'entries need')} review · /review`);
    out.push(`Liquid total · ${fmtRp(d.liquid)}`);
    const span = `the last ${msgPlural(d.fullMonths, 'full month', 'full months')}`;
    if (!d.fullMonths) out.push('Runway · not enough history yet (needs one full month of entries)');
    else if (!d.needAvg) out.push(`Runway · no "need" spending in ${span}`);
    else out.push(`Runway · ${(d.liquid / d.needAvg).toFixed(1)} months ("need" spending ${fmtRp(d.needAvg)} a month over ${span})`);
    return out.join('\n');
  },
  cashAdjusted(real, diff, id) {
    return `✅ Cash set to ${fmtRp(real)}. Logged ${fmtRp(Math.abs(diff))} as unrecorded cash (#${id}) · /undo`;
  },
  cashMatches(real) {
    return `Cash matches at ${fmtRp(real)}. Nothing to log.`;
  },
  cashUsage() {
    return '❓ How much cash do you have? Send e.g. "/cash 150000".';
  },
  help() {
    return [
      'Send a message or a receipt photo to log an entry, e.g. "makan padang 25rb".',
      '/undo · void the last entry, or one by id, e.g. /undo or /undo 25',
      '/last · show the latest entries, e.g. /last or /last 10',
      '/review · list entries that need review, e.g. /review',
      '/ok · confirm entries that need review, e.g. /ok or /ok 16 25',
      '/summary · show a month in numbers, e.g. /summary or /summary 2026-10',
      '/balance · show account balances, e.g. /balance',
      '/cash <amount> · set real cash, e.g. /cash 150000',
      '/help · show this list, e.g. /help',
    ].join('\n');
  },
  unknownCommand() {
    return "Unknown command. Send /help to see what's available.";
  },
  nudge(n) {
    return `${msgPlural(n, 'entry', 'entries')} today. Anything missing?`;
  },
};
function cTrue(x) {
  return x === true || String(x).toUpperCase() === 'TRUE';
}

function cNum(x) {
  const n = Number(x);
  return Number.isFinite(n) ? n : 0;
}

function cIdNum(row) {
  return parseInt(String(row.id).replace(/\D/g, ''), 10) || 0;
}

// "150000", "150.000", "150,000.00", "150rb", "1,5jt" -> integer rupiah, or null
function cParseAmount(arg) {
  const m = /^(?:rp|idr)?\s*(\d+(?:[.,]\d+)*)\s*(rb|k|ribu|jt|juta)?$/i.exec(String(arg || '').trim());
  if (!m) return null;
  // cents ("100.000,00", "150,000.00", "150000.00") are dropped; every other separator groups thousands
  if (!m[2]) return Number(m[1].replace(/[.,]\d{2}$/, '').replace(/[.,]/g, ''));
  const mult = /^(jt|juta)$/i.test(m[2]) ? 1e6 : 1e3;
  // with a suffix a separator is a decimal ("1,5jt"), unless it groups thousands ("1.500rb")
  const num = /^\d{1,3}([.,]\d{3})+$/.test(m[1]) ? m[1].replace(/[.,]/g, '') : m[1].replace(',', '.');
  return Math.round(Number(num) * mult);
}

function cStatus(t) {
  return String(t.status).toLowerCase();
}

function cById(a, b) {
  return cIdNum(a) - cIdNum(b);
}

// "25", "T0025", "#t25", separated by spaces or commas -> {rows, unknown: [token]}
function cPick(arg, transactions) {
  const rows = [];
  const unknown = [];
  for (const token of String(arg || '').split(/[\s,]+/).filter(Boolean)) {
    const m = /^#?t?0*(\d+)$/i.exec(token);
    const row = m && transactions.find((t) => cIdNum(t) === Number(m[1]));
    if (!row) unknown.push(token);
    else if (!rows.includes(row)) rows.push(row);
  }
  return { rows, unknown };
}

// With ids: void exactly those entries, or nothing when one of them is unknown or already void
function cUndoIds(arg, transactions) {
  const { rows, unknown } = cPick(arg, transactions);
  const bad = [...unknown, ...rows.filter((t) => cStatus(t) === 'void').map((t) => '#' + t.id)];
  if (bad.length) return { reply: MSG.badIds(bad, 'void'), appendRows: [], voidIds: [] };
  const voidIds = rows.map((t) => t.id);
  return { reply: MSG.voided(voidIds), appendRows: [], voidIds };
}

function cReview(transactions) {
  const rows = transactions.filter((t) => cStatus(t) === 'needs_review').sort(cById);
  return { reply: rows.length ? MSG.reviewList(rows) : MSG.reviewNone(), appendRows: [], voidIds: [] };
}

// No ids: confirm every entry that needs review. With ids: exactly those, or nothing when one is not waiting
function cOk(arg, transactions) {
  const none = { appendRows: [], voidIds: [], okIds: [] };
  let rows = transactions.filter((t) => cStatus(t) === 'needs_review').sort(cById);
  if (String(arg || '').trim()) {
    const pick = cPick(arg, transactions);
    const bad = [...pick.unknown, ...pick.rows.filter((t) => cStatus(t) !== 'needs_review').map((t) => '#' + t.id)];
    if (bad.length) return { ...none, reply: MSG.badIds(bad, 'confirm') };
    rows = pick.rows;
  }
  if (!rows.length) return { ...none, reply: MSG.reviewNone() };
  const okIds = rows.map((t) => t.id);
  return { ...none, reply: MSG.confirmed(okIds), okIds };
}

// Newest first; 5 unless a number is given
function cLast(arg, transactions) {
  const n = Math.min(Math.max(parseInt(arg, 10) || 5, 1), 30);
  const rows = transactions.filter((t) => cStatus(t) !== 'void').sort(cById).reverse().slice(0, n);
  return { reply: MSG.last(rows), appendRows: [], voidIds: [] };
}

function cUndo(transactions) {
  const live = transactions.filter((t) => String(t.status).toLowerCase() !== 'void');
  if (!live.length) return { reply: MSG.nothingToVoid(), appendRows: [], voidIds: [] };
  const last = live.reduce((a, b) => (cIdNum(b) > cIdNum(a) ? b : a));
  const batch = live.filter((t) => t.id === last.id || (last.batch_id && t.batch_id === last.batch_id));
  const voidIds = batch.map((t) => t.id);
  return { reply: MSG.voided(voidIds), appendRows: [], voidIds };
}

function cBalance(accounts) {
  const rows = accounts.map((a) => ({ account: a.account, balance: cNum(a.balance), liquid: cTrue(a.liquid) }));
  const total = rows.filter((a) => a.liquid).reduce((sum, a) => sum + a.balance, 0);
  return { reply: MSG.balance(rows, total), appendRows: [], voidIds: [] };
}

function cCash(arg, { accounts, nextIdNum, inbox, now, text }) {
  const real = cParseAmount(arg);
  if (real === null) return { reply: MSG.cashUsage(), appendRows: [], voidIds: [] };
  const cash = accounts.find((a) => String(a.account).toLowerCase() === 'cash');
  const diff = real - cNum(cash && cash.balance);
  if (!diff) return { reply: MSG.cashMatches(real), appendRows: [], voidIds: [] };

  const j = new Date(Date.parse(now) + 7 * 3600000).toISOString();
  const id = 'T' + String(Number(nextIdNum)).padStart(4, '0');
  const row = {
    id,
    inbox_update_id: inbox.update_id,
    batch_id: 'B' + inbox.update_id,
    created_at: j.slice(0, 19) + '+07:00',
    txn_date: j.slice(0, 10),
    txn_time: j.slice(11, 16),
    type: diff < 0 ? 'expense' : 'income',
    amount: Math.abs(diff),
    account: 'Cash',
    to_account: '',
    category_id: 'unrecorded-cash',
    nature: '',
    merchant: '',
    note: 'Cash count adjustment',
    items: '',
    receipt_total: '',
    irregular: false,
    source: 'adjustment',
    recurring_id: '',
    raw_input: text,
    tg_file_id: '',
    confidence: 1,
    status: 'ok',
  };
  return { reply: MSG.cashAdjusted(real, diff, id), appendRows: [row], voidIds: [] };
}

// 'YYYY-MM' moved by n months
function cMonthAdd(ym, n) {
  const [y, m] = ym.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1 + n, 1)).toISOString().slice(0, 7);
}

function cDay(t) {
  return String(t.txn_date).slice(0, 10);
}

function cSum(rows) {
  return rows.reduce((sum, t) => sum + cNum(t.amount), 0);
}

// [{name, amount}] largest first, from rows grouped by key(row)
function cTotals(rows, key) {
  const map = new Map();
  for (const t of rows) map.set(key(t), (map.get(key(t)) || 0) + cNum(t.amount));
  return [...map].map(([name, amount]) => ({ name, amount })).sort((a, b) => b.amount - a.amount);
}

// arg: '' (the current month in Jakarta) or 'YYYY-MM'. All totals are computed here, never by the LLM.
function cSummary(arg, { transactions, categories, accounts, now }) {
  const none = { appendRows: [], voidIds: [] };
  const today = new Date(Date.parse(now) + 7 * 3600000).toISOString().slice(0, 10);
  const thisMonth = today.slice(0, 7);
  const month = String(arg || '').trim() || thisMonth;
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) return { ...none, reply: MSG.summaryUsage() };

  const cats = {};
  for (const c of categories || []) cats[c.id] = c;
  const name = (t) => (cats[t.category_id] || {}).name || t.category_id;
  const group = (t) => (cats[t.category_id] || {}).group || 'Other';
  const isType = (type) => (t) => String(t.type).toLowerCase() === type;
  const nature = (n) => (t) => String(t.nature || '').toLowerCase() === n;

  const live = transactions.filter((t) => cStatus(t) !== 'void' && t.source !== 'opening');
  const rows = live.filter((t) => cDay(t).slice(0, 7) === month);
  if (!rows.length) return { ...none, reply: MSG.summaryEmpty(month) };
  const allExpenses = live.filter(isType('expense'));
  const expenses = rows.filter(isType('expense'));
  const incomes = rows.filter(isType('income'));
  const wants = expenses.filter(nature('want'));

  const weekend = (t) => [0, 6].includes(new Date(cDay(t) + 'T00:00:00Z').getUTCDay());
  const bucket = (t) => {
    const h = parseInt(String(t.txn_time || '').slice(0, 2), 10);
    if (!(h >= 0 && h <= 23)) return '';
    return h < 5 || h >= 22 ? 'night' : h < 11 ? 'morning' : h < 17 ? 'afternoon' : 'evening';
  };

  // 12 months ending with the summary month
  const from = cMonthAdd(month, -11);
  const irregular12 = allExpenses.filter((t) => cTrue(t.irregular) && cDay(t).slice(0, 7) >= from && cDay(t).slice(0, 7) <= month);

  // Runway: liquid total / average "need" expense of the last 3 full months that have entries behind them
  const openings = (accounts || []).map((a) => String(a.opening_date || '').slice(0, 10)).filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));
  const start = (openings.length ? openings : live.map(cDay)).sort()[0];
  const fullMonths = [-3, -2, -1].map((n) => cMonthAdd(thisMonth, n)).filter((ym) => start && ym + '-01' >= start);
  const needs = allExpenses.filter((t) => nature('need')(t) && fullMonths.includes(cDay(t).slice(0, 7)));
  const liquid = cSum((accounts || []).filter((a) => cTrue(a.liquid)).map((a) => ({ amount: a.balance })));

  return {
    ...none,
    reply: MSG.summary({
      month,
      to: month === thisMonth ? today : '',
      income: cSum(incomes),
      expense: cSum(expenses),
      groups: cTotals(expenses, group).map((g) => ({ ...g, subs: cTotals(expenses.filter((t) => group(t) === g.name), name) })),
      need: cSum(expenses.filter(nature('need'))),
      want: cSum(wants),
      topWant: cTotals(wants, name).slice(0, 3),
      wantWeekday: cSum(wants.filter((t) => !weekend(t))),
      wantWeekend: cSum(wants.filter(weekend)),
      wantTimes: ['morning', 'afternoon', 'evening', 'night']
        .map((b) => ({ name: b, amount: cSum(wants.filter((t) => bucket(t) === b)) }))
        .filter((b) => b.amount),
      irregular: expenses
        .filter((t) => cTrue(t.irregular))
        .map((t) => ({ txn_date: cDay(t), amount: cNum(t.amount), name: name(t), label: t.note || t.merchant || '' })),
      irregularAvg: cSum(irregular12) / 12,
      freelance: cSum(incomes.filter((t) => t.category_id === 'income-freelance')),
      review: rows.filter((t) => cStatus(t) === 'needs_review').length,
      liquid,
      fullMonths: fullMonths.length,
      needAvg: fullMonths.length ? cSum(needs) / fullMonths.length : 0,
    }),
  };
}

function runCommand({ text, transactions, accounts, categories, nextIdNum, inbox, now }) {
  const m = /^\/(\w+)(?:@\w+)?(?:\s+([\s\S]*))?$/.exec(String(text || '').trim());
  const cmd = m ? m[1].toLowerCase() : '';
  if (cmd === 'undo') return String(m[2] || '').trim() ? cUndoIds(m[2], transactions) : cUndo(transactions);
  if (cmd === 'review') return cReview(transactions);
  if (cmd === 'ok') return cOk(m[2], transactions);
  if (cmd === 'last') return cLast(m[2], transactions);
  if (cmd === 'summary') return cSummary(m[2], { transactions, categories, accounts, now });
  if (cmd === 'balance') return cBalance(accounts);
  if (cmd === 'cash') return cCash(m[2], { accounts, nextIdNum, inbox, now, text });
  if (cmd === 'help') return { reply: MSG.help(), appendRows: [], voidIds: [] };
  return { reply: MSG.unknownCommand(), appendRows: [], voidIds: [] };
}

// Entries dated today that the user logged (not void, not opening or adjustment rows)
function countToday(transactions, today) {
  return transactions.filter(
    (t) =>
      String(t.txn_date).slice(0, 10) === today &&
      String(t.status).toLowerCase() !== 'void' &&
      t.source !== 'opening' &&
      t.source !== 'adjustment',
  ).length;
}
const inbox = $('Start').first().json;
// A retried /undo would void one more batch, so an interrupted command is never re-run.
if (inbox.retry) throw new Error('it was interrupted and may already have run; check /balance first');
const transactions = $('Transactions').all().map((i) => i.json).filter((t) => t.id); // empty tab gives one {} item
const idNum = (t) => parseInt(String(t.id).replace(/\D/g, ''), 10) || 0;
const result = runCommand({
  text: inbox.text,
  transactions,
  accounts: $('Accounts').all().map((i) => i.json),
  categories: $('Categories').all().map((i) => i.json).filter((c) => c.id),
  nextIdNum: transactions.reduce((n, t) => Math.max(n, idNum(t)), 0) + 1,
  inbox,
  now: new Date().toISOString(),
});
return [{ json: { inbox, ...result } }];
